#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxCoins(vector<int>& nums) {
        vector<int> vals;
        vals.push_back(1);
        for (int x : nums) {
            if (x > 0) vals.push_back(x);
        }
        vals.push_back(1);
        int n = vals.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));

        for (int len = 2; len < n; ++len) {
            for (int left = 0; left < n - len; ++left) {
                int right = left + len;
                for (int k = left + 1; k < right; ++k) {
                    int coins = dp[left][k] + dp[k][right] + vals[left] * vals[k] * vals[right];
                    if (coins > dp[left][right]) {
                        dp[left][right] = coins;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
};

class Solution {
    public int maxCoins(int[] nums) {
        int[] vals = new int[nums.length + 2];
        int n = 1;
        vals[0] = 1;
        for (int x : nums) {
            if (x > 0) vals[n++] = x;
        }
        vals[n++] = 1;

        int[][] dp = new int[n][n];
        for (int len = 2; len < n; ++len) {
            for (int left = 0; left < n - len; ++left) {
                int right = left + len;
                for (int k = left + 1; k < right; ++k) {
                    int coins = dp[left][k] + dp[k][right] + vals[left] * vals[k] * vals[right];
                    if (coins > dp[left][right]) {
                        dp[left][right] = coins;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

